<?php require __DIR__.'/../src/bootstrap.php';require_owner();$id=isset($_GET['id'])?(int)$_GET['id']:null;$x=$id?find_item('users',$id):[];if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['username']);$p=$_POST['password']??'';$u=['username'=>$n,'role'=>$_POST['role']??'editor','enabled'=>isset($_POST['enabled'])];if($p!=='')$u['password']=password_hash($p,PASSWORD_DEFAULT);else $u['password']=$x['password']??'';save_item('users',$u,$id);header('Location:users.php');exit;}$page=$id?'تعديل حساب':'حساب جديد';require __DIR__.'/includes/header.php';?><h1><?=$page?></h1><form method="post" class="panel form"><div class="fields"><label>اسم المستخدم<input name="username" value="<?=e($x['username']??'')?>" required></label><label>كلمة المرور<?=$id?' (اتركها فارغة لعدم التغيير)':''?><input name="password" type="password" <?=!$id?'required':''?>></label><label>الدور<select name="role"><option value="editor">Editor - محتوى</option><option value="manager">Manager - إدارة</option><option value="owner">Owner - مالك</option></select></label></div><label class="check"><input type="checkbox" name="enabled" <?=($x['enabled']??true)?'checked':''?>> حساب نشط</label><button class="btn">💾 حفظ الحساب</button></form><?php require __DIR__.'/includes/footer.php';?>